     1|export function renderAdminPanel(logoUri: string): string {
     2|  return `<!doctype html>
     3|<html lang="en">
     4|<head>
     5|<meta charset="utf-8">
     6|<meta name="viewport" content="width=device-width, initial-scale=1">
     7|<title>VitaHero Admin</title>
     8|<link rel="icon" href="${logoUri}">
     9|<link rel="preconnect" href="https://fonts.googleapis.com">
    10|<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    11|<link href="https://fonts.googleapis.com/css2?family=Host+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet">
    12|<style>
    13|*{margin:0;padding:0;box-sizing:border-box}
    14|:root{
    15|  --orange:#F47B20;--orange-d:#D9641A;--orange-soft:#FCE5D1;
    16|  --blue:#1FA2DD;--blue-d:#1380B8;--blue-soft:#D6EFFA;
    17|  --yellow:#FDB813;--yellow-soft:#FFF1CC;
    18|  --purple:#8B5CF6;
    19|  --ink:#0F172A;--ink-soft:#475569;--ink-faint:#94A3B8;
    20|  --canvas:#F8FAFC;--surface:#FFFFFF;--muted:#F1F5F9;
    21|  --hair:#E2E8F0;
    22|  --good:#10B981;--watch:#F59E0B;--alert:#EF4444;
    23|  --radius:20px;--radius-sm:12px;--radius-xs:8px;
    24|  --shadow:0 1px 3px rgba(15,23,42,.08),0 4px 16px rgba(15,23,42,.06);
    25|  --shadow-lg:0 8px 30px rgba(15,23,42,.1);
    26|  --sidebar:260px;--sidebar-collapsed:76px;
    27|}
    28|body{font-family:'Host Grotesk',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:var(--canvas);color:var(--ink);font-size:14px;line-height:1.5;-webkit-font-smoothing:antialiased}
    29|
    30|/* ── Login ── */
    31|.login-wrap{min-height:100vh;display:grid;grid-template-columns:1.05fr 1fr}
    32|.login-brand{position:relative;overflow:hidden;display:flex;flex-direction:column;padding:48px 44px;color:#fff;min-height:100vh}
    33|.login-brand .bg-img{position:absolute;inset:0;background:url('https://r2-pub.rork.com/projects/0cso3uprrwvti6zjwr0jl/assets/6cdc1d51-87b7-4ac2-b9f4-aa840c15f557.png') center/cover no-repeat;opacity:.38}
    34|.login-brand .bg-grad{position:absolute;inset:0;background:linear-gradient(160deg,rgba(244,123,32,.82) 0%,rgba(31,162,221,.78) 55%,rgba(15,23,42,.72) 100%)}
    35|.login-brand>*{position:relative;z-index:1}
    36|.login-brand .brand-top{display:flex;align-items:center;gap:12px}
    37|.brand-top .brand-logo{height:54px;width:auto;filter:drop-shadow(0 2px 4px rgba(0,0,0,.2))}
    38|.login-brand .spacer{flex:1}
    39|.login-brand .quote{max-width:440px}
    40|.login-brand .quote .q-mark{font-size:56px;line-height:.6;font-weight:700;opacity:.5;margin-bottom:8px;font-family:Georgia,serif}
    41|.login-brand .quote h1{font-size:34px;font-weight:700;line-height:1.18;letter-spacing:-.7px;margin-bottom:16px}
    42|.login-brand .quote p{font-size:16px;line-height:1.65;opacity:.92}
    43|.login-brand .quote .author{margin-top:20px;font-size:13px;font-weight:600;opacity:.72;letter-spacing:.3px;text-transform:uppercase}
    44|.login-form{display:flex;align-items:center;justify-content:center;padding:40px 28px;background:var(--canvas);min-height:100vh}
    45|.login-card{background:var(--surface);border-radius:var(--radius);padding:48px 40px;max-width:400px;width:100%;box-shadow:var(--shadow-lg);border:1px solid var(--hair)}
    46|.login-card .head{margin-bottom:32px}
    47|.login-card .head .label{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.6px;color:var(--orange);margin-bottom:10px}
    48|.login-card .head h2{font-size:27px;font-weight:700;letter-spacing:-.5px;color:var(--ink);line-height:1.2;margin-bottom:8px}
    49|.login-card .head .sub{color:var(--ink-soft);font-size:14px;line-height:1.5}
    50|.login-card .field-label{display:block;font-size:13px;font-weight:600;color:var(--ink-soft);margin-bottom:8px}
    51|.login-card input{width:100%;padding:14px 16px;border:2px solid var(--hair);border-radius:var(--radius-sm);font-size:15px;font-family:inherit;outline:none;transition:border .2s,box-shadow .2s;background:var(--surface)}
    52|.login-card input:focus{border-color:var(--orange);box-shadow:0 0 0 3px var(--orange-soft)}
    53|.login-card .btn{width:100%;padding:15px;background:linear-gradient(90deg,var(--orange),var(--blue));color:#fff;border:none;border-radius:var(--radius-sm);font-size:15px;font-weight:600;font-family:inherit;cursor:pointer;transition:opacity .2s,transform .1s;margin-top:6px}
    54|.login-card .btn:hover{opacity:.92}.login-card .btn:active{transform:scale(.98)}
    55|.login-card .err{color:var(--alert);font-size:13px;margin-top:12px;display:none;background:#FEE2E2;padding:11px 16px;border-radius:var(--radius-sm);text-align:center;line-height:1.5}
    56|.login-card .foot{margin-top:26px;text-align:center;font-size:12px;color:var(--ink-faint);line-height:1.6}
    57|.login-card .foot b{color:var(--ink-soft)}
    58|
    59|/* ── App shell ── */
    60|.app{display:none;min-height:100vh}
    61|.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sidebar);background:linear-gradient(180deg,#0F172A 0%,#1E293B 100%);color:#fff;z-index:100;display:flex;flex-direction:column;transition:width .25s cubic-bezier(.4,0,.2,1);box-shadow:4px 0 24px rgba(15,23,42,.12)}
    62|.sidebar.collapsed{width:var(--sidebar-collapsed)}
    63|.sidebar-header{display:flex;align-items:center;justify-content:space-between;padding:18px 16px;border-bottom:1px solid rgba(255,255,255,.08);min-height:72px;gap:10px}
    64|.sidebar .brand{display:flex;align-items:center;gap:12px;overflow:hidden;white-space:nowrap}
    65|.sidebar .brand-logo{height:34px;width:auto;flex-shrink:0}
    66|.sidebar .brand-text{font-size:20px;font-weight:700;letter-spacing:-.3px;transition:opacity .15s}
    67|.sidebar .brand-text span{color:var(--orange)}
    68|.sidebar.collapsed .brand-text{display:none}
    69|.toggle-btn{width:34px;height:34px;border-radius:10px;background:rgba(255,255,255,.08);border:none;color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:background .2s;flex-shrink:0}
    70|.toggle-btn:hover{background:rgba(255,255,255,.16)}
    71|.toggle-btn .ico-expand,.toggle-btn .ico-collapse{display:none}
    72|.sidebar.collapsed .toggle-btn .ico-expand{display:block}
    73|.sidebar:not(.collapsed) .toggle-btn .ico-collapse{display:block}
    74|.sidebar nav{flex:1;padding:12px 10px;overflow-y:auto}
    75|.sidebar nav a{display:flex;align-items:center;gap:14px;padding:12px 14px;margin-bottom:4px;color:rgba(255,255,255,.6);text-decoration:none;font-size:14px;font-weight:500;border-radius:10px;cursor:pointer;transition:all .2s;position:relative;white-space:nowrap}
    76|.sidebar nav a:hover{background:rgba(255,255,255,.06);color:#fff}
    77|.sidebar nav a.active{background:rgba(244,123,32,.14);color:var(--orange)}
    78|.sidebar nav a .ico{width:20px;height:20px;flex-shrink:0;opacity:.85}
    79|.sidebar nav a.active .ico{opacity:1}
    80|.sidebar nav a .label{white-space:nowrap;opacity:1;transition:opacity .15s}
    81|.sidebar.collapsed nav a .label{display:none}
    82|.sidebar.collapsed nav a{padding:14px 0;justify-content:center}
    83|.sidebar.collapsed nav a .ico{width:22px;height:22px}
    84|.sidebar-footer{padding:16px;border-top:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:space-between;gap:10px}
    85|.sidebar-footer .ver{font-size:11px;color:var(--ink-faint);transition:opacity .15s}
    86|.sidebar.collapsed .sidebar-footer .ver{display:none}
    87|.sidebar-footer .logout{background:rgba(255,255,255,.08);border:none;color:#fff;border-radius:10px;padding:9px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:background .2s;flex-shrink:0}
    88|.sidebar-footer .logout:hover{background:rgba(239,68,68,.18);color:var(--alert)}
    89|.sidebar.collapsed .sidebar-footer{justify-content:center}
    90|
    91|.main{margin-left:var(--sidebar);padding:28px 36px;min-height:100vh;transition:margin-left .25s cubic-bezier(.4,0,.2,1)}
    92|.sidebar.collapsed~.main{margin-left:var(--sidebar-collapsed)}
    93|.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:32px;gap:16px}
    94|.topbar h2{font-size:24px;font-weight:700;letter-spacing:-.3px}
    95|.topbar .breadcrumb{color:var(--ink-faint);font-size:13px;margin-top:2px}
    96|
    97|/* ── Cards ── */
    98|.card{background:var(--surface);border:1px solid var(--hair);border-radius:var(--radius);padding:24px;margin-bottom:20px;box-shadow:var(--shadow)}
    99|.card-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:12px;flex-wrap:wrap}
   100|.card-title{font-size:17px;font-weight:700;display:flex;align-items:center;gap:10px}
   101|.card-title .ico{width:18px;height:18px;color:var(--orange)}
   102|
   103|/* ── Stats ── */
   104|.stat-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:20px;margin-bottom:24px}
   105|.stat-card{background:var(--surface);border:1px solid var(--hair);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow);display:flex;align-items:flex-start;gap:16px;transition:transform .2s,box-shadow .2s}
   106|.stat-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg)}
   107|.stat-icon{width:46px;height:46px;border-radius:13px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
   108|.stat-icon svg{width:24px;height:24px}
   109|.stat-card.orange .stat-icon{background:rgba(244,123,32,.12);color:var(--orange)}
   110|.stat-card.green .stat-icon{background:rgba(16,185,129,.12);color:var(--good)}
   111|.stat-card.blue .stat-icon{background:rgba(31,162,221,.12);color:var(--blue)}
   112|.stat-card.amber .stat-icon{background:rgba(253,184,19,.12);color:#B45309}
   113|.stat-card .info{flex:1}
   114|.stat-card .label{font-size:12px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;font-weight:600}
   115|.stat-card .value{font-size:32px;font-weight:700;letter-spacing:-.5px}
   116|
   117|/* ── Banner ── */
   118|.banner{padding:14px 18px;border-radius:var(--radius-sm);margin-bottom:20px;font-size:13px;font-weight:500;display:none;align-items:center;gap:10px}
   119|.banner.warn{background:var(--yellow-soft);color:#92400E;display:flex}
   120|.banner.info{background:var(--blue-soft);color:var(--blue-d);display:flex}
   121|.banner svg{width:18px;height:18px;flex-shrink:0}
   122|
   123|/* ── Forms ── */
   124|.form-group{margin-bottom:18px}
   125|.form-group label{display:block;font-weight:600;margin-bottom:8px;font-size:13px;color:var(--ink-soft)}
   126|.form-group input,.form-group textarea,.form-group select{width:100%;padding:12px 16px;border:1.5px solid var(--hair);border-radius:var(--radius-sm);font-size:14px;outline:none;font-family:inherit;background:var(--surface);transition:border .2s,box-shadow .2s}
   127|.form-group input:focus,.form-group textarea:focus,.form-group select:focus{border-color:var(--orange);box-shadow:0 0 0 3px var(--orange-soft)}
   128|.form-group textarea{min-height:220px;resize:vertical;font-family:'SF Mono',Consolas,'Courier New',monospace;font-size:13px;line-height:1.6}
   129|.checkbox-row{display:flex;align-items:center;gap:10px;margin-bottom:14px}
   130|.checkbox-row input{width:18px;height:18px;accent-color:var(--orange);cursor:pointer}
   131|.checkbox-row label{margin:0;cursor:pointer;font-size:14px;color:var(--ink-soft)}
   132|
   133|/* ── Buttons ── */
   134|.btn-primary{padding:12px 24px;background:linear-gradient(90deg,var(--orange),var(--blue));color:#fff;border:none;border-radius:var(--radius-sm);font-size:14px;font-weight:600;font-family:inherit;cursor:pointer;transition:opacity .2s,transform .1s;display:inline-flex;align-items:center;gap:8px}
   135|.btn-primary:hover{opacity:.92}.btn-primary:active{transform:scale(.98)}.btn-primary:disabled{opacity:.45;cursor:not-allowed}
   136|.btn-secondary{padding:10px 18px;background:var(--surface);border:1.5px solid var(--hair);border-radius:var(--radius-sm);color:var(--ink-soft);font-size:13px;font-weight:600;font-family:inherit;cursor:pointer;transition:all .2s;display:inline-flex;align-items:center;gap:8px}
   137|.btn-secondary:hover{background:var(--muted);border-color:var(--ink-faint);color:var(--ink)}
   138|.btn-orange{padding:8px 18px;background:var(--orange);color:#fff;border:none;border-radius:var(--radius-xs);font-size:13px;font-weight:600;font-family:inherit;cursor:pointer;transition:background .2s}
   139|.btn-orange:hover{background:var(--orange-d)}.btn-orange:disabled{opacity:.45;cursor:not-allowed}
   140|.btn-sm{padding:8px 16px;font-size:13px;border:1.5px solid var(--hair);background:var(--surface);border-radius:var(--radius-xs);cursor:pointer;font-family:inherit;font-weight:500;color:var(--ink-soft);transition:all .2s;display:inline-flex;align-items:center;gap:6px}
   141|.btn-sm:hover{background:var(--muted);border-color:var(--ink-faint);color:var(--ink)}
   142|
   143|/* ── Tables ── */
   144|.table-wrap{overflow-x:auto;border-radius:var(--radius-sm);border:1px solid var(--hair)}
   145|table{width:100%;border-collapse:collapse}
   146|th{text-align:left;padding:12px 14px;font-size:11px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.4px;border-bottom:2px solid var(--hair);font-weight:600;background:var(--muted)}
   147|td{padding:12px 14px;border-bottom:1px solid var(--hair);font-size:13px}tr:hover td{background:var(--muted)}
   148|.empty-state{text-align:center;padding:40px 24px;color:var(--ink-soft)}
   149|.empty-state svg{width:48px;height:48px;color:var(--ink-faint);margin-bottom:12px}
   150|
   151|/* ── Badges ── */
   152|.badge{display:inline-flex;align-items:center;gap:6px;padding:4px 12px;border-radius:50px;font-size:11px;font-weight:600}
   153|.badge::before{content:'';width:7px;height:7px;border-radius:50%}
   154|.badge.green{background:rgba(16,185,129,.13);color:#166534}.badge.green::before{background:var(--good)}
   155|.badge.amber{background:rgba(245,158,11,.13);color:#92400E}.badge.amber::before{background:var(--watch)}
   156|.badge.gray{background:var(--muted);color:var(--ink-soft)}.badge.gray::before{background:var(--ink-faint)}
   157|.badge.red{background:rgba(239,68,68,.13);color:#991B1B}.badge.red::before{background:var(--alert)}
   158|.badge.blue{background:var(--blue-soft);color:var(--blue-d)}.badge.blue::before{background:var(--blue)}
   159|
   160|/* ── Misc ── */
   161|.tab-content{display:none}.tab-content.active{display:block}
   162|.guide-mono{font-family:'SF Mono',Consolas,monospace;font-size:12px}
   163|.guide-tag{color:var(--blue)}.guide-tag-opt{color:var(--ink-soft)}
   164|.flow-list{padding-left:22px;color:var(--ink-soft);line-height:2}
   165|.flow-list b{color:var(--ink)}
   166|.loading{text-align:center;padding:48px;color:var(--ink-soft)}
   167|.spinner{display:inline-block;width:28px;height:28px;border:3px solid var(--hair);border-top-color:var(--orange);border-radius:50%;animation:spin .8s linear infinite}
   168|@keyframes spin{to{transform:rotate(360deg)}}
   169|.results-table{max-height:420px;overflow-y:auto;border-radius:var(--radius-sm)}
   170|.import-toolbar{display:flex;gap:12px;margin-bottom:18px;flex-wrap:wrap;align-items:center}
   171|.import-toolbar .hint{color:var(--ink-faint);font-size:13px}
   172|.search-row{display:flex;gap:12px;margin-bottom:18px;align-items:center;flex-wrap:wrap}
   173|.search-row input{flex:1;min-width:220px;padding:12px 16px;border:1.5px solid var(--hair);border-radius:var(--radius-sm);font-size:14px;outline:none;font-family:inherit;transition:border .2s,box-shadow .2s}
   174|.search-row input:focus{border-color:var(--orange);box-shadow:0 0 0 3px var(--orange-soft)}
   175|
   176|@media(max-width:900px){.login-wrap{grid-template-columns:1fr}.login-brand{display:none}.login-form{padding:24px 20px;min-height:100vh}}
   177|@media(max-width:768px){
   178|  .sidebar{transform:translateX(-100%);width:var(--sidebar)}
   179|  .sidebar.open{transform:translateX(0)}
   180|  .sidebar.collapsed{width:var(--sidebar)}
   181|  .main{margin-left:0;padding:18px}
   182|  .sidebar.collapsed~.main{margin-left:0}
   183|  .mobile-menu{display:flex!important}
   184|}
   185|</style>
   186|</head>
   187|<body>
   188|<div class="login-wrap" id="loginScreen">
   189|  <div class="login-brand">
   190|    <div class="bg-img"></div>
   191|    <div class="bg-grad"></div>
   192|    <div class="brand-top"><img src="${logoUri}" alt="VitaHero" class="brand-logo"></div>
   193|    <div class="spacer"></div>
   194|    <div class="quote">
   195|      <div class="q-mark">&ldquo;</div>
   196|      <h1>Track Your Kid&rsquo;s Growth Heroically!</h1>
   197|      <p>School camps, diet plans, doctor support &amp; rewards &mdash; all in one place. VitaHero puts your child&rsquo;s health in heroic hands.</p>
   198|      <div class="author">VitaHero &mdash; Your child&rsquo;s health companion</div>
   199|    </div>
   200|  </div>
   201|  <div class="login-form">
   202|    <div class="login-card">
   203|      <div class="head">
   204|        <div class="label">Admin Portal</div>
   205|        <h2>Welcome back</h2>
   206|        <p class="sub">Import student data &amp; manage parent invitations</p>
   207|      </div>
   208|      <label class="field-label" for="adminKeyInput">Admin API Key</label>
   209|      <input type="password" id="adminKeyInput" placeholder="Enter your admin key" onkeydown="if(event.key==='Enter')doLogin()">
   210|      <button class="btn" onclick="doLogin()">Enter Admin Panel</button>
   211|      <div class="err" id="loginErr">Invalid admin key. Please try again.</div>
   212|      <div class="foot"><b>Authorized personnel only.</b><br>Your data is secure &amp; private. DPDP compliant.</div>
   213|    </div>
   214|  </div>
   215|</div>
   216|<div class="app" id="mainApp">
   217|  <aside class="sidebar" id="sidebar">
   218|    <div class="sidebar-header">
   219|      <div class="brand">
   220|        <img src="${logoUri}" alt="VitaHero" class="brand-logo">
   221|        <span class="brand-text">Vita<span>Hero</span></span>
   222|      </div>
   223|      <button class="toggle-btn" id="sidebarToggle" onclick="toggleSidebar()" aria-label="Toggle sidebar">
   224|        <span class="ico-collapse"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M9 3v18"/><path d="m16 15-3-3 3-3"/></svg></span>
   225|        <span class="ico-expand"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M15 3v18"/><path d="m8 9 3 3-3 3"/></svg></span>
   226|      </button>
   227|    </div>
   228|    <nav>
   229|      <a id="tab-overview" class="active" onclick="switchTab('overview')">
   230|        <span class="ico"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect width="7" height="9" x="3" y="3" rx="1"/><rect width="7" height="5" x="14" y="3" rx="1"/><rect width="7" height="9" x="14" y="12" rx="1"/><rect width="7" height="5" x="3" y="16" rx="1"/></svg></span>
   231|        <span class="label">Overview</span>
   232|      </a>
   233|      <a id="tab-import" onclick="switchTab('import')">
   234|        <span class="ico"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" x2="12" y1="3" y2="15"/></svg></span>
   235|        <span class="label">Import Data</span>
   236|      </a>
   237|      <a id="tab-parents" onclick="switchTab('parents')">
   238|        <span class="ico"><svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span>
   239|        <span class="label">Parents</span>
