<style>
*{margin:0;padding:0;box-sizing:border-box}
:root{
  --orange:#F47B20;--orange-d:#D9641A;--orange-soft:#FCE5D1;
  --blue:#1FA2DD;--blue-d:#1380B8;--blue-soft:#D6EFFA;
