<script>
var adminKey=localStorage.getItem('vitahero_admin_key')||'';
var docRowCounter=0;
function api(m,p,b){var o={method:m,headers:{'Content-Type':'application/json','X-Admin-Key':adminKey}};if(b)o.body=JSON.stringify(b);return fetch(p,o).then(function(r){if(!r.ok)return r.json().then(function(e){throw new Error(e.error||('HTTP '+r.status))});return r.json()})}
function doLogin(){var k=document.getElementById('adminKeyInput').value.trim();if(!k)return;adminKey=k;api('GET','/api/admin/stats').then(function(){localStorage.setItem('vitahero_admin_key',adminKey);document.getElementById('loginScreen').style.display='none';document.getElementById('mainApp').style.display='block';var sb=document.getElementById('sidebar');if(localStorage.getItem('vitahero_sidebar_collapsed')==='1')sb.classList.add('collapsed');loadOverview();checkDevMode()}).catch(function(){adminKey='';document.getElementById('loginErr').style.display='block'})}
function doLogout(){localStorage.removeItem('vitahero_admin_key');adminKey='';location.reload()}
if(adminKey){api('GET','/api/admin/stats').then(function(){document.getElementById('loginScreen').style.display='none';document.getElementById('mainApp').style.display='block';var sb=document.getElementById('sidebar');if(localStorage.getItem('vitahero_sidebar_collapsed')==='1')sb.classList.add('collapsed');loadOverview();checkDevMode()}).catch(function(){adminKey=''})}
function toggleSidebar(){var sb=document.getElementById('sidebar');sb.classList.toggle('collapsed');localStorage.setItem('vitahero_sidebar_collapsed',sb.classList.contains('collapsed')?'1':'0')}
function checkDevMode(){fetch('/ping').then(function(r){return r.json()}).then(function(d){if(d.dev_mode)document.getElementById('devModeBanner').style.display='flex'}).catch(function(){})}
function switchTab(t){var ts=['overview','import','parents','doctors','history'];for(var i=0;i<ts.length;i++){document.getElementById('tab-'+ts[i]).classList.toggle('active',ts[i]===t);document.getElementById('content-'+ts[i]).classList.toggle('active',ts[i]===t)}var titles={overview:'Overview',import:'Import Data',parents:'Parents',doctors:'Doctors',history:'Import History'};document.getElementById('pageTitle').textContent=titles[t];if(t==='overview')loadOverview();if(t==='parents')loadParents();if(t==='doctors')loadDoctorsTab();if(t==='history')loadHistory()}
function loadOverview(){api('GET','/api/admin/stats').then(function(d){document.getElementById('stat-parents').textContent=d.provisionedParents||0;document.getElementById('stat-active').textContent=d.activeParents||0;document.getElementById('stat-kids').textContent=d.importedKids||0;document.getElementById('stat-invites').textContent=d.invitesSent||0}).catch(function(){})}
function parseCSVLine(l){var r=[],c='',q=false;for(var i=0;i<l.length;i++){var ch=l[i];if(ch=='"')q=!q;else if(ch===','&&!q){r.push(c);c=''}else c+=ch}r.push(c);return r}
function parseCSV(t){var lines=t.trim().split(String.fromCharCode(10));if(lines.length<2)return[];var headers=parseCSVLine(lines[0]);var rows=[];for(var i=1;i<lines.length;i++){var line=lines[i].trim();if(!line)continue;var vals=parseCSVLine(line);var row={};for(var j=0;j<headers.length;j++)row[headers[j]]=(vals[j]||'').trim();rows.push(row)}return rows}
function downloadTemplate(){var header='phone,studentName,parentName,gender,grade,age,schoolCode,schoolName,campDate,campTitle,heightCm,weightKg,dental,eyesight,nutrition,studentId';var sample='9876543210,Aarav Sharma,Rahul Sharma,M,Class 3,7,OAK2026,Oakridge International School,2026-07-15,Annual Health Camp,115,22,GOOD,GOOD,GOOD,STU001';var csv=header+String.fromCharCode(10)+sample;var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='vitahero_import_template.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url)}
function doImport(){var csv=document.getElementById('csvInput').value.trim();if(!csv){alert('Please paste CSV data first.');return}var rows=parseCSV(csv);if(rows.length===0){alert('No data rows found in CSV.');return}if(rows.length>2000){alert('Too many rows (max 2000). Split the file.');return}var dry=document.getElementById('dryRun').checked;var inv=document.getElementById('sendInvites').checked;if(!dry&&!confirm('Import '+rows.length+' rows'+(inv?' and send SMS invitations':'')+'?'))return;var btn=document.getElementById('importBtn');btn.disabled=true;btn.textContent=dry?'Processing (dry run)...':'Importing...';api('POST','/api/admin/import',{rows:rows,dryRun:dry,sendInvites:dry?false:inv,filename:'admin_panel_'+new Date().toISOString().slice(0,10)}).then(function(r){btn.disabled=false;btn.textContent='Import Data';showImportResults(r);if(!dry)loadOverview()}).catch(function(e){btn.disabled=false;btn.textContent='Import Data';alert('Import failed: '+e.message)})}
function showImportResults(r){var el=document.getElementById('importResults');el.style.display='block';var s='<div style="margin-bottom:10px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:12px"><span class="badge '+(r.dryRun?'amber':'green')+'">'+(r.dryRun?'DRY RUN':'IMPORTED')+'</span> <b>'+r.total+'</b> rows: <span style="color:var(--good);font-weight:600">'+r.created+' created</span>, <span style="color:var(--blue);font-weight:600">'+r.updated+' updated</span>, <span style="color:var(--alert);font-weight:600">'+r.errors+' errors</span>';if(r.invited>0)s+=', <span style="color:var(--orange);font-weight:600">'+r.invited+' invited</span>';s+='</div>';document.getElementById('importSummary').innerHTML=s;var h='<table><thead><tr><th>Row</th><th>Phone</th><th>Student</th><th>Status</th><th>Message</th></tr></thead><tbody>';for(var i=0;i<r.results.length;i++){var row=r.results[i];var bg=row.status==='created'?'green':row.status==='updated'?'blue':row.status==='skipped'?'amber':'red';h+='<tr><td>'+row.row+'</td><td>'+(row.phone||'')+'</td><td>'+(row.student||'')+'</td><td><span class="badge '+bg+'">'+row.status+'</span></td><td>'+(row.message||'')+'</td></tr>'}h+='</tbody></table>';document.getElementById('importTableWrap').innerHTML=h}
function loadParents(){var s=document.getElementById('parentSearch').value.trim();var qs=s?('?q='+encodeURIComponent(s)):'';document.getElementById('parentsTable').innerHTML='<div class="loading"><div class="spinner"></div></div>';api('GET','/api/admin/parents'+qs).then(function(rows){if(!rows||rows.length===0){document.getElementById('parentsTable').innerHTML='<div class="empty-state"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg><p>No provisioned parents found.</p></div>';return}var h='<table><thead><tr><th>Phone</th><th>Parent Name</th><th>School</th><th>Kids</th><th>Invited</th><th>Status</th><th>Action</th></tr></thead><tbody>';for(var i=0;i<rows.length;i++){var p=rows[i];var inv=p.invited_at?'<span class="badge green">Yes ('+(p.invite_count||0)+')</span>':'<span class="badge gray">No</span>';var st=p.is_logged_in?'<span class="badge green">Active</span>':'<span class="badge amber">Pending</span>';var btn=p.invited_at?'Re-send':'Send Invite';h+='<tr><td>'+(p.phone||'')+'</td><td>'+(p.name||'Parent')+'</td><td>'+(p.school_name||'-')+'</td><td>'+(p.kid_count||0)+'</td><td>'+inv+'</td><td>'+st+'</td><td><button class="btn-orange" onclick="sendInvite('+(p.phone||'')+')">'+btn+'</button></td></tr>'}h+='</tbody></table>';document.getElementById('parentsTable').innerHTML=h}).catch(function(e){document.getElementById('parentsTable').innerHTML='<p style="color:var(--alert);padding:12px;font-weight:500;font-size:12px">Error: '+e.message+'</p>'})}
function sendInvite(phone){if(!phone)return;if(!confirm('Send invitation SMS to '+phone+'?'))return;api('POST','/api/admin/invite',{phones:[phone],force:true}).then(function(d){alert('Invitation sent: '+d.invited+' successful, '+d.skipped.length+' skipped.');loadParents()}).catch(function(e){alert('Failed to send invite: '+e.message)})}
function loadHistory(){document.getElementById('historyTable').innerHTML='<div class="loading"><div class="spinner"></div></div>';api('GET','/api/admin/import-batches').then(function(rows){if(!rows||rows.length===0){document.getElementById('historyTable').innerHTML='<div class="empty-state"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v5l5 0"/><path d="M3.05 13A9 9 0 1 0 6 5.3L3 8"/><path d="M12 7v5l4 2"/></svg><p>No import batches yet.</p></div>';return}var h='<table><thead><tr><th>Date</th><th>Filename</th><th>Total</th><th>Created</th><th>Updated</th><th>Errors</th><th>Invited</th><th>Type</th></tr></thead><tbody>';for(var i=0;i<rows.length;i++){var b=rows[i];var dt=b.created_at?new Date(b.created_at).toLocaleString():'-';var tp=b.dry_run?'<span class="badge amber">Dry Run</span>':'<span class="badge green">Live</span>';h+='<tr><td>'+dt+'</td><td>'+(b.filename||'-')+'</td><td>'+b.total+'</td><td>'+b.created+'</td><td>'+b.updated+'</td><td>'+b.errors+'</td><td>'+b.invited+'</td><td>'+tp+'</td></tr>'}h+='</tbody></table>';document.getElementById('historyTable').innerHTML=h}).catch(function(e){document.getElementById('historyTable').innerHTML='<p style="color:var(--alert);padding:12px;font-weight:500;font-size:12px">Error: '+e.message+'</p>'})}
function loadDoctorsTab(){loadCampOptions();loadDoctors()}
function loadCampOptions(){api('GET','/api/admin/camps').then(function(camps){var sel=document.getElementById('docCampSelect');if(!camps||camps.length===0){sel.innerHTML='<option value="">No camps available - import data first</option>';return}var h='<option value="">Select a camp...</option>';for(var i=0;i<camps.length;i++){var c=camps[i];h+='<option value="'+c.id+'">'+(c.title||'Camp')+' - '+(c.school_name||'')+' ('+(c.date||'')+')</option>'}sel.innerHTML=h}).catch(function(){document.getElementById('docCampSelect').innerHTML='<option value="">Failed to load camps</option>'})}
function addDoctorRow(){docRowCounter++;var container=document.getElementById('doctorRowsContainer');var div=document.createElement('div');div.className='doc-row';div.setAttribute('data-row',docRowCounter);div.innerHTML='<div class="form-group"><input type="text" class="doc-name" placeholder="Dr. ..."></div><div class="form-group"><input type="text" class="doc-phone" placeholder="9876543210"></div><div class="form-group"><input type="text" class="doc-specialty" placeholder="General Paediatrics" value="General Paediatrics"></div><div class="form-group"><input type="text" class="doc-hospital" placeholder="Hospital / Clinic"></div><button class="btn-remove" onclick="removeDoctorRow(this)"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button>';container.appendChild(div);updateRemoveButtons();updateDocCount()}
function removeDoctorRow(btn){var row=btn.closest('.doc-row');if(row)row.remove();updateRemoveButtons();updateDocCount()}
function updateRemoveButtons(){var rows=document.querySelectorAll('#doctorRowsContainer .doc-row');for(var i=0;i<rows.length;i++){var btn=rows[i].querySelector('.btn-remove');if(btn)btn.style.visibility=rows.length>1?'visible':'hidden'}}
function updateDocCount(){var rows=document.querySelectorAll('#doctorRowsContainer .doc-row');var el=document.getElementById('docRowCount');if(el)el.textContent=rows.length+' doctor'+(rows.length!==1?'s':'')+' queued'}
function generateDoctors(){var camp=document.getElementById('docCampSelect').value;var rows=document.querySelectorAll('#doctorRowsContainer .doc-row');var doctors=[];var errors=[];for(var i=0;i<rows.length;i++){var name=rows[i].querySelector('.doc-name').value.trim();var phone=rows[i].querySelector('.doc-phone').value.trim();var spec=rows[i].querySelector('.doc-specialty').value.trim()||'General Paediatrics';var hosp=rows[i].querySelector('.doc-hospital').value.trim();if(!name&&!phone)continue;if(!name||!phone){errors.push('Row '+(i+1)+': Missing name or phone');continue}doctors.push({doctor_name:name,phone:phone,specialty:spec,hospital:hosp})}if(doctors.length===0){document.getElementById('genDocResult').innerHTML='<div class="banner warn" style="display:flex">Please fill at least one doctor with name and phone.</div>';return}if(!camp){document.getElementById('genDocResult').innerHTML='<div class="banner warn" style="display:flex">Please select a camp first.</div>';return}if(errors.length>0&&!confirm(errors.length+' row(s) have errors and will be skipped. Continue with '+doctors.length+' valid doctor(s)?'))return;var btn=document.getElementById('genDocBtn');btn.disabled=true;btn.textContent='Generating ('+doctors.length+')...';api('POST','/api/admin/doctors/generate-batch',{doctors:doctors,school_camp_id:camp}).then(function(r){btn.disabled=false;btn.textContent='Generate Credentials';var cls=r.errors>0?'warn':'info';var msg='<div class="banner '+cls+'" style="display:flex"><span>&#10003;</span> <b>'+r.created+'</b> credential'+(r.created!==1?'s':'')+' created, <b>'+r.errors+'</b> error'+(r.errors!==1?'s':'')+'. '+r.total+' total processed.';if(r.errors>0){var errList='';for(var j=0;j<r.results.length;j++){if(r.results[j].status==='error')errList+='<br>&nbsp;&nbsp;&bull; Row '+r.results[j].row+': '+r.results[j].message}msg+=errList}msg+='</div>';document.getElementById('genDocResult').innerHTML=msg;if(r.created>0){resetDoctorForm();loadDoctors()}}).catch(function(e){btn.disabled=false;btn.textContent='Generate Credentials';document.getElementById('genDocResult').innerHTML='<div class="banner warn" style="display:flex">Error: '+e.message+'</div>'})}
function resetDoctorForm(){var container=document.getElementById('doctorRowsContainer');container.innerHTML='<div class="doc-row" data-row="0"><div class="form-group"><input type="text" class="doc-name" placeholder="Dr. Ananya Rao"></div><div class="form-group"><input type="text" class="doc-phone" placeholder="9876543210"></div><div class="form-group"><input type="text" class="doc-specialty" placeholder="General Paediatrics" value="General Paediatrics"></div><div class="form-group"><input type="text" class="doc-hospital" placeholder="Rainbow Children\\'s Hospital"></div><button class="btn-remove" onclick="removeDoctorRow(this)" style="visibility:hidden"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button></div>';docRowCounter=0;updateDocCount()}
function loadDoctors(){document.getElementById('doctorsTable').innerHTML='<div class="loading"><div class="spinner"></div></div>';api('GET','/api/admin/doctors').then(function(rows){if(!rows||rows.length===0){document.getElementById('doctorsTable').innerHTML='<div class="empty-state"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4.8 2.3A.3.3 0 1 0 5 2H4a2 2 0 0 0-2 2v5a6 6 0 0 0 6 6v0a6 6 0 0 0 6-6V4a2 2 0 0 0-2-2h-1a.2.2 0 1 0 .2.3"/><path d="M8 15v1a6 6 0 0 0 6 6v0a6 6 0 0 0 6-6v-4"/><circle cx="20" cy="10" r="2"/></svg><p>No doctor credentials generated yet.</p></div>';return}var h='<table><thead><tr><th>Doctor</th><th>Phone</th><th>Camp</th><th>School</th><th>Camp Date</th><th>Status</th><th>Login</th><th>Action</th></tr></thead><tbody>';for(var i=0;i<rows.length;i++){var d=rows[i];var st=d.assignment_status==='ACTIVE'?'<span class="badge green">Active</span>':'<span class="badge red">Revoked</span>';var lg=d.is_logged_in?'<span class="badge blue">Logged In</span>':'<span class="badge gray">Offline</span>';var rv=d.assignment_status==='ACTIVE'?'<button class="btn-sm" style="color:var(--alert);border-color:rgba(239,68,68,.3)" onclick="revokeDoctor('+d.assignment_id+')">Revoke</button>':'-';h+='<tr><td><b>'+(d.doctor_name||'')+'</b></td><td>'+(d.phone||'')+'</td><td>'+(d.camp_title||'-')+'</td><td>'+(d.school_name||'-')+'</td><td>'+(d.camp_date||'-')+'</td><td>'+st+'</td><td>'+lg+'</td><td>'+rv+'</td></tr>'}h+='</tbody></table>';document.getElementById('doctorsTable').innerHTML=h}).catch(function(e){document.getElementById('doctorsTable').innerHTML='<p style="color:var(--alert);padding:12px;font-weight:500;font-size:12px">Error: '+e.message+'</p>'})}
